<script setup lang="ts">
import {computed, nextTick, onBeforeUnmount, onMounted, ref, watch} from 'vue'
import {ElMessage, ElMessageBox} from 'element-plus'
import './engineering.css'
import BusinessTimeInput from './BusinessTimeInput.vue'
import NumberEntries from './NumberEntries.vue'
import {formatClock,formatDateTime,stageGuidance} from './presentation'
import {stageForArea} from './journey'
import {learningTasks} from './learning'
import {readSession,removeSession,writeSession} from './session'
import NaturalData from './NaturalData.vue'
import {naturalScalar} from './naturalData'

const props=defineProps<{projectId:string; repository?:string; area?:string; sections?:string[]; embedded?:boolean; artifacts?:any[]}>()
const emit=defineEmits<{(e:'project-created', id:string):void; (e:'changed'):void; (e:'navigate', area:string):void; (e:'trace', value:any):void}>()
const state=ref<any>({objects:[],history:[],relations:[]}), drafts=ref<any[]>([]), impact=ref<any>({paths:[],unknown:[],tests:[],test_mapping_gaps:[]})
const evidence=ref<any>({conclusions:[],tests:{},runs:[],architecture:{}}), capabilities=ref<any>({}), cases=ref<any[]>([])
const tab=ref('rules'), busy=ref(false), error=ref(''), ruleId=ref(''), sessionId=ref(''), trainingId=ref(''), score=ref<any>(null)
const events=ref<any[]>([]), history=ref<any[]>([]), historyOpen=ref(false), architectureReviewOpen=ref(false), specText=ref(''), specimen=ref<any>(null), outcome=ref('')
const ruleForm=ref({id:'',title:'容量与取消规则',domain:'campus',capacity:2,cancel_requires_approval:false,waitlist_enabled:false,quotas:'{}',window_start:0,window_end:1440})
const action=ref({user:'同学甲',group:'普通',quantity:1,start:0,end:60,at:0})
const testForm=ref({id:'',title:'公开验收测试',path:'test_enrollment.py',framework:'unittest',code_paths:'enrollment.py',rule_ids:[] as string[]})
const testEditor=ref<HTMLDetailsElement|null>(null)
const codePath=ref('enrollment.py'), trusted=ref(false), executionMode=ref('native'), full=ref(true)
const archForm=ref({id:'',title:'入口鉴权约束',scope:'enrollment.py',forbidden_imports:'',required_calls:'ensure_authenticated',entry_functions:'enroll,cancel,approve',reason:'每个业务入口必须先检查身份，不能绕过鉴权。',exception_reason:'',exception_until:''})
const negotiation=ref({existing:2,incoming:1,group:'普通',group_existing:0,requested_start:0,requested_end:60,allow_waitlist:false,allow_capacity_increase:false,allow_window_expansion:false,capacity_limit:100,preference:'least_change'})
const outcomeForm=ref({title:'变更后的运行观察',observation:'',metrics:'{}',decision:'OBSERVE',rationale:''})
const outcomeRecords=computed(()=>drafts.value.filter(d=>d.kind==='OUTCOME').slice().reverse())
const rules=computed(()=>state.value.objects.filter((o:any)=>o.kind==='RULE'))
const tests=computed(()=>state.value.objects.filter((o:any)=>o.kind==='TEST'))
const architectures=computed(()=>state.value.objects.filter((o:any)=>o.kind==='ARCHITECTURE'))
const currentRule=computed(()=>rules.value.find((o:any)=>o.id===ruleId.value))
const candidates=computed(()=>drafts.value.filter(d=>d.kind==='REQUIREMENT'&&d.status==='DRAFT'))
const architectureCandidates=computed(()=>candidates.value.filter(d=>d.content.changes.some((c:any)=>c.kind==='ARCHITECTURE')))
const negotiations=computed(()=>drafts.value.filter(d=>d.kind==='NEGOTIATION').slice().reverse())
const sessions=computed(()=>drafts.value.filter(d=>d.kind==='PROTOTYPE').slice().reverse())
const trainings=computed(()=>drafts.value.filter(d=>d.kind==='TRAINING').slice().reverse())
const training=computed(()=>trainings.value.find(d=>d.id===trainingId.value))
const running=computed(()=>evidence.value.runs.some((r:any)=>['QUEUED','RUNNING','CANCELLING'].includes(r.status)))
const names:Record<string,string>={RULE:'业务规则',CODE:'代码',TEST:'测试对应关系',ARCHITECTURE:'工程设计约束',PASS:'通过',FAIL:'未通过',UNKNOWN:'未知，需补证据',STALE:'已失效，待复验',QUEUED:'排队中',RUNNING:'运行中',CANCELLING:'正在取消',CANCELLED:'已取消',SUCCEEDED:'执行完成',ERROR:'执行错误',TIMEOUT:'超时',INTERRUPTED:'服务中断',NOT_CONFIGURED:'未登记',VIOLATION:'不符合约束',EXEMPT:'有期限的例外',FEASIBLE:'有可行方案',INFEASIBLE:'当前条件无解',DRAFT:'待处理',ADOPTED:'已采用',SUBMITTED:'已提交',enrolled:'已成功',waiting:'候补中',pending_cancel:'待取消审批',cancelled:'已取消',campus:'校园报名',inventory:'库存扣减',reservation:'预约冲突',CONFIRMED:'已确认',MIGRATED:'整理历史记录',BASELINE_CONFIRMED:'确认新需求版本',VERIFICATION_QUEUED:'提交复验',VERIFICATION_FINISHED:'复验结束',ARCHITECTURE_CHECKED:'检查工程设计',NEGOTIATION_SOLVED:'完成协商计算',NEGOTIATION_ADOPTED:'采用协商方案',TRAINING_STARTED:'开始实践',TRAINING_CHANGE:'确认容量调整',TRAINING_SUBMITTED:'提交实践结果',IMPACT_REVIEWED:'人工审阅影响',CASE_CREATED:'创建领域案例',OUTCOME_CONFIRMED:'确认运行观察与决策'}
const label=(s:string)=>names[s]||naturalScalar(s)
const short=(s:string)=>s?.slice(0,8)||'未记录'
const versionName=(id:string)=>{const index=state.value.history.findIndex((b:any)=>b.id===id);return index<0?'历史版本':`需求版本 ${index+1}`}
function ruleChanges(c:any){
 const old=state.value.objects.find((o:any)=>o.id===c.id)?.content
 const rows=[['capacity','容量上限',(v:any)=>String(v)],['window_start','开放时间',formatClock],['window_end','结束时间',formatClock],['cancel_requires_approval','取消审批',(v:any)=>v?'需要审批':'立即生效'],['waitlist_enabled','容量不足时',(v:any)=>v?'允许候补':'不允许候补'],['quotas','分组配额',(v:any)=>Object.entries(v||{}).map(([k,n])=>`${k}：${n}`).join('、')||'未设置']] as const
 return rows.filter(([key])=>!old||JSON.stringify(old[key])!==JSON.stringify(c.content[key])).map(([key,title,format])=>({title,before:old?format(old[key] as never):'未设置',after:format(c.content[key] as never)}))
}
const readableNegotiation=(value:string)=>value.replace(/允许窗口扩大为 (\d+)—(\d+)/g,(_,a,b)=>`开放时间调整为 ${formatClock(Number(a))} 至 ${formatClock(Number(b))}`).replace('保留现有数量 + 新增全部成功 > 当前容量','现有数量与新增申请之和超过当前容量').replace('该组现有数量 + 该组新增数量 > 组配额','该组现有数量与新增申请之和超过分组配额')
const pretty=(v:any)=>JSON.stringify(v,null,2)
const list=(text:string)=>text.split(/[,，\n]/).map(x=>x.trim()).filter(Boolean)
const basis=()=>({expected_baseline_id:state.value.baseline_id,confirmed:true})
const tasks=computed(()=>learningTasks(state.value,drafts.value,evidence.value,impact.value))
const lesson=computed(()=>stageGuidance[stageForArea(tab.value)])
const suggested=computed(()=>{
 if(candidates.value.length)return tasks.value[0]
 if(impact.value.test_mapping_gaps?.length)return tasks.value[4]
 return tasks.value.find(t=>t.state!=='已完成')
})
const next=computed(()=>suggested.value?.detail||'本轮需求、验证和观察已记录，可到过程复盘整理下一轮改进。')
const actionName=computed(()=>({campus:'提交报名',inventory:'扣减库存',reservation:'提交预约'} as any)[currentRule.value?.content.domain]||'提交申请')
const personLabel=computed(()=>currentRule.value?.content.domain==='inventory'?'订单编号':'参与者姓名')
const prototypeCurrent=computed(()=>specimen.value?.baseline_id===state.value.baseline_id)

const sectionNames:Record<string,string>={rules:'规则与版本',prototype:'体验需求',negotiate:'需求协商',architecture:'架构守护',change:'代码版本',verify:'影响与复验',outcome:'运行观察',training:'过程复盘'}
const linkedSpecs=computed(()=>(props.artifacts||[]).filter(a=>['Specification','EngineeringIntent'].includes(a.kind)))
let restoredDraft=''
function draftKey(){return `engineering:${props.projectId}:${state.value.baseline_id}`}
function resetForms(){
 ruleForm.value={id:'',title:'容量与取消规则',domain:'campus',capacity:2,cancel_requires_approval:false,waitlist_enabled:false,quotas:'{}',window_start:0,window_end:1440}
 testForm.value={id:'',title:'公开验收测试',path:'test_enrollment.py',framework:'unittest',code_paths:'enrollment.py',rule_ids:[]}
 archForm.value={id:'',title:'入口鉴权约束',scope:'enrollment.py',forbidden_imports:'',required_calls:'ensure_authenticated',entry_functions:'enroll,cancel,approve',reason:'每个业务入口必须先检查身份，不能绕过鉴权。',exception_reason:'',exception_until:''}
 negotiation.value={existing:2,incoming:1,group:'普通',group_existing:0,requested_start:0,requested_end:60,allow_waitlist:false,allow_capacity_increase:false,allow_window_expansion:false,capacity_limit:100,preference:'least_change'}
 outcomeForm.value={title:'变更后的运行观察',observation:'',metrics:'{}',decision:'OBSERVE',rationale:''};specText.value=''
}
function restoreForms(){
 const key=draftKey();if(restoredDraft===key)return;restoredDraft=key
 const saved=readSession<any>(key);if(!saved){resetForms();return}
 if(saved.ruleForm)ruleForm.value=saved.ruleForm;if(saved.testForm)testForm.value={...testForm.value,...saved.testForm,rule_ids:saved.testForm.rule_ids||[]}
 if(saved.archForm)archForm.value=saved.archForm;if(saved.negotiation)negotiation.value=saved.negotiation
 if(saved.outcomeForm)outcomeForm.value=saved.outcomeForm;if(typeof saved.specText==='string')specText.value=saved.specText
}
function storeForms(){if(!props.projectId||!state.value.baseline_id)return;writeSession(draftKey(),{ruleForm:ruleForm.value,testForm:testForm.value,archForm:archForm.value,negotiation:negotiation.value,outcomeForm:outcomeForm.value,specText:specText.value})}

async function request(path:string,method='GET',body?:any){
 const response=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)})
 const value=await response.json();if(!response.ok)throw new Error(typeof value.detail==='string'?value.detail:'操作未完成，请核对输入后重试。');return value
}
const api=(path:string,method='GET',body?:any)=>request(`/projects/${props.projectId}/engineering`+path,method,body)
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e:any){if(e!=='cancel'&&e!=='close'){error.value=e.message||'操作未完成';ElMessage.error(error.value)}}finally{busy.value=false}}
async function reload(){
 if(!props.projectId)return
 const id=props.projectId
 const values=await Promise.all([api(''),api('/drafts'),api('/impact'),api('/evidence'),api('/execution-capabilities'),api('/events')])
 if(id!==props.projectId)return
 ;[state.value,drafts.value,impact.value,evidence.value,capabilities.value,events.value]=values
 restoreForms()
 emit('trace',{objects:state.value.objects,relations:state.value.relations,history:state.value.history,events:events.value,evidence:evidence.value,tasks:tasks.value})
 if(!rules.value.some((o:any)=>o.id===ruleId.value))ruleId.value=rules.value[0]?.id||''
 if(sessionId.value)specimen.value=drafts.value.find(d=>d.id===sessionId.value)||null
 if(!trainingId.value)trainingId.value=trainings.value[0]?.id||''
}
async function createCase(domain:string){await act(async()=>{
 const selected=cases.value.find(c=>c.domain===domain)
 await ElMessageBox.confirm(`将创建独立的${selected?.title}项目副本，并确认公开初始容量 ${selected?.capacity}、代码及测试映射。不会修改当前项目，也不调用模型或使用密钥。`,'打开可运行案例',{confirmButtonText:'确认并创建'})
 const p=await request('/engineering/cases','POST',{domain,confirmed:true});emit('project-created',p.id);tab.value='rules';ElMessage.success('案例已创建，先查看规则，再体验原型')
})}
function editRule(o:any){ruleForm.value={id:o.id,title:o.title,...o.content,quotas:pretty(o.content.quotas)};ruleId.value=o.id;tab.value='rules'}
function newRule(){ruleForm.value={id:'',title:'新业务规则',domain:'campus',capacity:2,cancel_requires_approval:false,waitlist_enabled:false,quotas:'{}',window_start:0,window_end:1440}}
async function draftRule(){await act(async()=>{
 const {id,title,quotas,...content}=ruleForm.value
 await api('/drafts','POST',{expected_baseline_id:state.value.baseline_id,title:`${id?'修订':'新增'}：${title}`,changes:[{...(id?{id}:{}),kind:'RULE',title,content:{...content,quotas:JSON.parse(quotas)}}]})
 await reload();ElMessage.success('候选已保存，正式规则还没有变化；请在下方审阅后确认')
})}
async function accept(d:any){await act(async()=>{
 await ElMessageBox.confirm('确认后将形成新的需求版本，相关旧证据可能失效。请先核对候选与当前规则的差异。','确认正式修改',{confirmButtonText:'确认新需求版本'})
 await api(`/drafts/${d.id}/confirm`,'POST',{expected_baseline_id:d.baseline_id,confirmed:true});await reload();emit('changed');ElMessage.success('新需求版本已形成，请查看变化影响')
})}
async function remove(o:any){await act(async()=>{await ElMessageBox.confirm('只从新需求版本移除这项内容，历史修订仍保留；相关测试可能需要重新审阅。','确认移除');await api('/confirm','POST',{...basis(),title:'移除 '+o.title,changes:[{id:o.id,delete:true}]});await reload();emit('changed')})}
async function objectHistory(o:any){await act(async()=>{history.value=await api(`/objects/${o.id}/history`);historyOpen.value=true})}
watch(ruleId,()=>{sessionId.value='';specimen.value=null;outcome.value='';const c=currentRule.value?.content;if(c){negotiation.value.requested_start=c.window_start;negotiation.value.requested_end=Math.min(c.window_start+60,c.window_end);negotiation.value.capacity_limit=Math.max(100,c.capacity)}})
async function beginPrototype(){await act(async()=>{const d=await api('/prototypes','POST',{rule_id:ruleId.value,expected_baseline_id:state.value.baseline_id});sessionId.value=d.id;specimen.value=d;const c=currentRule.value.content;action.value={...action.value,quantity:1,at:c.window_start,start:c.window_start,end:Math.min(c.window_start+60,c.window_end)};outcome.value='预览已开始，请填写参与者并执行操作';await reload()})}
async function perform(event:string){await act(async()=>{const value=await api(`/prototypes/${sessionId.value}/actions`,'POST',{...action.value,event});specimen.value=value.session;outcome.value=(value.outcome.accepted?'操作成功：':'操作未接受：')+value.outcome.reason;await reload()})}
async function snapshot(){await act(async()=>{await ElMessageBox.confirm('只纳入 Git 已提交的当前版本；未提交修改及未跟踪文件不会执行。此操作不替你提交代码。','确认代码版本');await api('/code-snapshot','POST',basis());await reload();emit('changed')})}
async function registerTest(){await act(async()=>{
 if(!ruleId.value)throw new Error('请先选择测试要验证的业务规则')
 const {id,title,path,framework,code_paths}=testForm.value
 await ElMessageBox.confirm('请先在开发工具中检查该测试确实验证所选规则。系统只记录你审阅的映射，不会自动证明测试覆盖完整。','确认测试映射')
 await api('/confirm','POST',{...basis(),title:'人工审阅测试映射',changes:[{...(id?{id}:{}),kind:'TEST',title,content:{path,framework,code_paths:list(code_paths),rule_ids:testForm.value.rule_ids.length?testForm.value.rule_ids:[ruleId.value]}}]})
 await reload();emit('changed')
})}
async function editTest(t:any){testForm.value={id:t.id,title:t.title,path:t.content.path,framework:t.content.framework,code_paths:t.content.code_paths.join(','),rule_ids:[...(t.content.rule_ids||[])]};await nextTick();testEditor.value?.setAttribute('open','');testEditor.value?.scrollIntoView({block:'center'});testEditor.value?.querySelector<HTMLInputElement>('input')?.focus()}
async function reviewTest(t:any){await act(async()=>{await ElMessageBox.confirm(`请先核对 ${t.content.path} 是否覆盖当前规则，必要时在开发工具中修改并提交；不要仅为消除失效提示而直接确认。`,'重新审阅测试',{confirmButtonText:'已检查，确认当前映射'});await api('/confirm','POST',{...basis(),title:'重新审阅测试映射',changes:[{id:t.id,kind:t.kind,title:t.title,content:t.content}]});await reload();emit('changed')})}
async function registerCode(){await act(async()=>{await api('/confirm','POST',{...basis(),title:'登记业务代码及实现关系',changes:[{id:crypto.randomUUID(),kind:'CODE',title:codePath.value,content:{path:codePath.value}}]});await reload();emit('changed')})}
async function reviewImpact(){await act(async()=>{impact.value=await api('/impact-review','POST',basis());await reload();ElMessage.success('已记录你对当前变化影响的审阅')})}
async function verify(){await act(async()=>{
 if(executionMode.value==='native'&&!trusted.value)throw new Error('请先确认这是可信项目。本机执行不是安全沙箱。')
 await api('/runs','POST',{...basis(),mode:executionMode.value,trusted_project:trusted.value,full:full.value,request_id:crypto.randomUUID()});await reload();ElMessage.success('复验已进入后台队列，可以查看运行状态或取消')
})}
async function saveArchitecture(){await act(async()=>{const {id,title,forbidden_imports,required_calls,entry_functions,...content}=archForm.value;await api('/drafts','POST',{expected_baseline_id:state.value.baseline_id,title:'审阅架构约束：'+title,changes:[{...(id?{id}:{}),kind:'ARCHITECTURE',title,content:{...content,forbidden_imports:list(forbidden_imports),required_calls:list(required_calls),entry_functions:list(entry_functions)}}]});await reload();architectureReviewOpen.value=true;ElMessage.success('架构候选已保存，请在当前阶段审阅确认')})}
async function checkArchitecture(){await act(async()=>{await api('/architecture-check','POST',basis());await reload()})}
async function solve(){await act(async()=>{await api('/negotiations','POST',{...basis(),rule_id:ruleId.value,...negotiation.value});await reload()})}
async function adopt(d:any,index:number){await act(async()=>{await ElMessageBox.confirm('采用后只修改正式规则，不会自动修改业务代码。相关测试需重新审阅并复验。','采用协商方案');await api(`/negotiations/${d.id}/adopt`,'POST',{expected_baseline_id:d.baseline_id,confirmed:true,candidate_index:index});await reload();emit('changed')})}
async function exportSpec(){await act(async()=>{specText.value=(await api('/spec/export','POST',{document:specText.value})).document})}
function downloadSpec(){const url=URL.createObjectURL(new Blob([specText.value],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='intentflow-spec.md';a.click();URL.revokeObjectURL(url)}
async function importSpec(){await act(async()=>{await api('/spec/import','POST',{expected_baseline_id:state.value.baseline_id,document:specText.value});await reload();tab.value='rules';ElMessage.success('导入内容仅为候选，请核对后确认')})}
async function beginTraining(){await act(async()=>{const d=await api('/training','POST',{...basis(),rule_id:ruleId.value});trainingId.value=d.id;await reload();score.value=await api(`/training/${d.id}/score`)})}
async function trainingChange(){await act(async()=>{await ElMessageBox.confirm(`将当前实践规则的容量调整为 ${training.value.content.target_capacity}，相关测试需要重新核对和验证。`,'确认容量调整');await api(`/training/${trainingId.value}/change`,'POST',basis());await reload();emit('changed');score.value=await api(`/training/${trainingId.value}/score`)})}
async function submitTraining(){await act(async()=>{await api(`/training/${trainingId.value}/submit`,'POST',basis());await reload();score.value=training.value?.content.submission})}
async function saveOutcome(){await act(async()=>{await api('/outcomes','POST',{...basis(),...outcomeForm.value,metrics:JSON.parse(outcomeForm.value.metrics)});removeSession(draftKey());restoredDraft='';outcomeForm.value={title:'变更后的运行观察',observation:'',metrics:'{}',decision:'OBSERVE',rationale:''};await reload();emit('changed');ElMessage.success('已将运行观察、人工决策与当前需求版本及验证证据关联保存')})}
let timer:ReturnType<typeof setInterval>|undefined
watch(()=>props.area,value=>{if(value)tab.value=value},{immediate:true})
watch(tab,value=>{if(props.embedded)emit('navigate',value)})
watch(()=>props.projectId,()=>{state.value={objects:[],history:[],relations:[]};drafts.value=[];evidence.value={conclusions:[],tests:{},runs:[],architecture:{}};impact.value={paths:[],unknown:[],tests:[],test_mapping_gaps:[]};events.value=[];outcome.value='';ruleId.value='';sessionId.value='';specimen.value=null;trainingId.value='';score.value=null;specText.value='';trusted.value=false;reload().catch((e:any)=>{error.value=e.message})})
watch([ruleForm,testForm,archForm,negotiation,outcomeForm,specText],storeForms,{deep:true,flush:'post'})
onMounted(()=>{act(async()=>{cases.value=await request('/engineering/cases');await reload()});timer=setInterval(async()=>{if(!busy.value&&props.projectId&&running.value){try{await reload()}catch(e:any){error.value=e.message}}},1500)})
onBeforeUnmount(()=>{if(timer)clearInterval(timer)})
</script>

<template>
 <section class="engineering" :class="`eng-tab-${tab}`" v-loading="busy" :aria-busy="busy||running">
  <div v-if="!embedded" class="eng-title"><div><p class="eng-eyebrow">IntentFlow 软件工程实践</p><h1>需求与工程证据工作区</h1><p>先理解和确认规则，再用真实代码与测试检验。原型演示不等于代码验证。</p></div><el-button v-if="projectId" @click="act(reload)">刷新当前版本</el-button></div>
  <el-alert v-if="error" :title="error" type="error" role="alert" show-icon :closable="false"/><span class="motion-status" role="status" aria-live="polite">{{busy?'正在更新工程数据…':running?'真实复验正在运行…':''}}</span>
  <div v-if="!projectId" class="eng-cases"><strong>从可运行案例开始</strong><el-button v-for="c in cases" :key="c.domain" @click="createCase(c.domain)">打开{{c.title}}案例</el-button><span>每个案例包含规则、代码和测试，可直接开始学习。</span></div>
  <el-alert v-if="!projectId" title="请选择已有项目，或点击上面的领域案例。案例包含已确认初始规则、代码与测试。" type="info" :closable="false"/>
  <template v-else-if="state.baseline">
   <section class="eng-next" aria-label="学习引导"><h2>{{sectionNames[tab]}}的学习任务</h2><p>{{lesson.goal}}</p><p><b>完成条件：</b>{{lesson.done}}</p><div class="lesson-next"><div><b>建议下一步：{{suggested?.title||'回顾本轮过程'}}</b><p>{{next}}</p></div><el-button type="primary" @click="tab=suggested?.area||'training'">{{suggested?'前往'+suggested.title:'前往过程复盘'}}</el-button></div><div class="eng-meta">需求版本 {{state.generation+1}}<span>代码{{state.baseline.code_commit?'已记录':'待提交'}}</span><el-tag :type="evidence.baseline_supported?'success':'warning'">{{evidence.baseline_supported?'已登记结论有证据支持':'证据待补齐或复验'}}</el-tag></div></section>
   <details class="learning-board"><summary>本轮任务看板（{{tasks.filter(t=>t.state==='已完成').length}} / {{tasks.length}} 项已有记录）</summary><p>状态来自已保存的成果；查看页面不会标记完成。需求变化后，原型与验证需要重新检查。</p><div class="task-board"><section v-for="status in ['可开始','待复验','待处理','已完成']" :key="status"><h3>{{status}}</h3><button v-for="task in tasks.filter(t=>t.state===status)" :key="task.id" @click="tab=task.area"><b>{{task.title}}</b><span>{{task.detail}}</span></button><p v-if="!tasks.some(t=>t.state===status)">暂无任务</p></section></div></details>
   <nav v-if="(sections||[]).length>1" class="eng-nav" aria-label="本阶段功能"><button v-for="id in sections" :key="id" :class="{active:tab===id}" @click="tab=id">{{sectionNames[id]}}</button></nav>
   <div class="eng-select" v-if="rules.length"><label for="active-rule">当前业务规则</label><select id="active-rule" v-model="ruleId"><option v-for="r in rules" :key="r.id" :value="r.id">{{r.title}}，第 {{r.number}} 次修订</option></select><span v-if="currentRule">{{label(currentRule.content.domain)}}，容量 {{currentRule.content.capacity}}</span></div>
   <aside v-if="currentRule&&['negotiate','outcome'].includes(tab)" class="context-card"><b>填写时对照：{{currentRule.title}}</b><p>容量 {{currentRule.content.capacity}}；开放 {{formatClock(currentRule.content.window_start)}} 至 {{formatClock(currentRule.content.window_end)}}；取消{{currentRule.content.cancel_requires_approval?'需要审批':'立即生效'}}；{{currentRule.content.waitlist_enabled?'允许候补':'不允许候补'}}；分组配额 {{Object.entries(currentRule.content.quotas||{}).map(([k,v])=>k+'：'+v).join('、')||'未设置'}}。</p><template v-if="tab==='outcome'"><p>当前证据：{{evidence.support_scope||'尚无完整验证结论'}}；最近复验 {{evidence.runs?.length?label(evidence.runs.at(-1).status):'尚未运行'}}。</p><details><summary>查看本轮验证结论</summary><NaturalData :value="evidence.conclusions"/></details></template></aside>

   <section v-if="tab==='rules'" class="eng-section">
    <article v-if="linkedSpecs.length" class="eng-card"><h2>本项目的需求与设计依据</h2><p>下面是同一项目已保存的分析记录。结构化规则必须按这些资料人工核对，不会把自然语言自动变成正式规则。旧轮次资料仅供参考。</p><details v-for="a in linkedSpecs" :key="a.id"><summary>{{a.title}}，{{a.current_iteration===false?'历史参考，需重新核对':'当前轮次'}}</summary><NaturalData :value="a.data"/></details></article>
    <div class="eng-grid"><article class="eng-card"><h2>正式规则</h2><p>“修改”只是填写候选；“确认新需求版本”才会改变正式规则。</p><div v-for="r in rules" :key="r.id" class="eng-record"><b>{{r.title}}</b><p>容量 {{r.content.capacity}}，取消{{r.content.cancel_requires_approval?'需要审批':'立即生效'}}，{{r.content.waitlist_enabled?'允许候补':'不允许候补'}}，窗口 {{formatClock(r.content.window_start)}} 至 {{formatClock(r.content.window_end)}}</p><el-button @click="editRule(r)">修改此规则</el-button><el-button @click="objectHistory(r)">历史修订</el-button><el-button type="danger" plain @click="remove(r)">从当前需求版本移除</el-button></div><p v-if="!rules.length">还没有正式规则。可填写右侧表单，或打开一个领域案例。</p><el-button @click="newRule">填写一条新规则</el-button></article>
     <article class="eng-card"><h2>{{ruleForm.id?'修订规则候选':'新规则候选'}}</h2><form @submit.prevent="draftRule" class="eng-form"><label>规则标题<input v-model="ruleForm.title" required maxlength="300"/></label><label>领域<select v-model="ruleForm.domain"><option value="campus">校园报名</option><option value="inventory">库存扣减</option><option value="reservation">预约冲突</option></select></label><label>容量上限<input v-model.number="ruleForm.capacity" type="number" min="1" max="100000" required/></label><div class="eng-pair"><BusinessTimeInput v-model="ruleForm.window_start" label="开放时间"/><BusinessTimeInput v-model="ruleForm.window_end" label="结束时间"/></div><label class="eng-check"><input v-model="ruleForm.cancel_requires_approval" type="checkbox"/>取消需要审批；审批前仍占容量</label><label class="eng-check"><input v-model="ruleForm.waitlist_enabled" type="checkbox"/>容量不足时允许候补</label><NumberEntries v-model="ruleForm.quotas" label="分组配额（可选）" name-label="分组名称" integer/><p v-if="ruleForm.window_end<=ruleForm.window_start" role="alert">结束时间必须晚于开放时间。跨日时请选择“次日”。</p><el-button type="primary" native-type="submit" :disabled="!ruleForm.quotas||ruleForm.window_end<=ruleForm.window_start">保存候选，等待确认</el-button></form></article></div>
    <article class="eng-card"><h2>待审阅候选</h2><p>请对照正式规则检查变化；过期候选不能直接确认。工程设计候选和规格导入也在这里审阅。</p><p v-if="!candidates.length">当前没有待确认候选。</p><div v-for="d in candidates" :key="d.id" class="eng-record"><b>{{d.content.title}}</b><span>，{{versionName(d.baseline_id)}}</span><details><summary>查看修改详情</summary><NaturalData :value="d.content.changes"/></details><div v-for="(c,i) in d.content.changes" :key="i"><p v-if="d.content.changes.length>1">{{c.delete?'移除':c.id?'修订':'新增'}}：{{c.title||state.objects.find((o:any)=>o.id===c.id)?.title||'未命名条目'}}</p><div v-if="c.kind==='RULE'&&!c.delete" class="eng-table-wrap"><table><thead><tr><th>修改项</th><th>当前规则</th><th>确认后</th></tr></thead><tbody><tr v-for="row in ruleChanges(c)" :key="row.title"><td>{{row.title}}</td><td>{{row.before}}</td><td>{{row.after}}</td></tr></tbody></table></div></div><el-button type="primary" :disabled="d.baseline_id!==state.baseline_id" @click="accept(d)">确认新需求版本</el-button><el-button @click="act(async()=>{await api(`/drafts/${d.id}/cancel`,'POST');await reload()})">放弃候选</el-button><span v-if="d.baseline_id!==state.baseline_id">候选已过期，请按最新规则重新填写。</span></div></article>
    <article class="eng-card"><h2>导入与导出需求文档</h2><p>可导出当前规则供讨论，修改后再导入审阅。请保留文件中的格式标记，确认后才会更新需求。</p><div class="eng-actions"><el-button @click="exportSpec">生成或更新规格文档</el-button><el-button :disabled="!specText" @click="downloadSpec">下载规格文件</el-button><el-button :disabled="!specText" @click="importSpec">读取修改，生成候选</el-button></div><textarea class="eng-spec" v-model="specText" rows="7" aria-label="规格文档内容" placeholder="先生成规格，或把之前导出的完整规格文件内容粘贴到这里。"/></article>
   </section>

   <section v-if="tab==='prototype'" class="eng-section"><article class="eng-card"><h2>体验已确认的需求规则</h2><p>这是规则模拟，不会修改项目代码，也不能作为测试通过的证据。规则变化后请新建预览；历史轨迹仍然保留。</p><el-button type="primary" :disabled="!ruleId" @click="beginPrototype">按当前规则开始预览</el-button><div v-if="sessions.length" class="eng-select"><label>已保存预览<select v-model="sessionId" @change="specimen=drafts.find(d=>d.id===sessionId)"><option v-for="s in sessions.filter(s=>s.content.rule_id===ruleId)" :key="s.id" :value="s.id">{{formatDateTime(s.created_at)}}，{{s.content.events.length}} 次操作{{s.baseline_id===state.baseline_id?'（当前规则）':'（历史规则）'}}</option></select></label></div><template v-if="specimen"><el-alert v-if="specimen.baseline_id!==state.baseline_id" title="这是旧需求版本的历史预览，只能查看。请按当前规则重新开始。" type="warning" :closable="false"/><div class="eng-form eng-fields"><label>{{personLabel}}<input v-model="action.user" :aria-label="personLabel"/></label><label>分组<input v-model="action.group"/></label><label v-if="currentRule?.content.domain==='inventory'">扣减数量<input v-model.number="action.quantity" type="number" min="1"/></label><BusinessTimeInput v-model="action.at" label="操作时间"/><BusinessTimeInput v-model="action.start" label="预约开始" v-if="currentRule?.content.domain==='reservation'"/><BusinessTimeInput v-model="action.end" label="预约结束" v-if="currentRule?.content.domain==='reservation'"/></div><div class="eng-actions"><el-button v-for="a in [{event:'enroll',title:actionName},{event:'cancel',title:'申请取消'},{event:'approve',title:'批准取消'},{event:'reject',title:'拒绝取消'}]" :key="a.event" :disabled="!prototypeCurrent||!action.user.trim()" @click="perform(a.event)">{{a.title}}</el-button></div><p role="status" class="eng-feedback">{{outcome}}</p><div class="eng-table-wrap"><table><thead><tr><th>参与者</th><th>分组</th><th>数量</th><th v-if="currentRule?.content.domain==='reservation'">预约时段</th><th>当前状态</th></tr></thead><tbody><tr v-for="(e,i) in specimen.content.state.entries" :key="i"><td>{{e.user}}</td><td>{{e.group}}</td><td>{{e.quantity}}</td><td v-if="currentRule?.content.domain==='reservation'">{{formatClock(e.start)}} 至 {{formatClock(e.end)}}</td><td>{{label(e.status)}}</td></tr></tbody></table></div><details><summary>查看操作轨迹</summary><ol><li v-for="(e,i) in specimen.content.events" :key="i">{{e.accepted?'接受':'拒绝'}}：{{e.reason}}</li></ol></details></template></article></section>

   <section v-if="tab==='change'" class="eng-section"><article class="eng-card"><h2>同一项目的代码版本</h2><p>在开发工具中修改下方仓库并提交，然后确认代码版本。需求、测试映射和复验均使用这里的提交，不会另建一份项目。</p><p class="eng-path">{{repository||'尚未连接仓库'}}</p><el-button :disabled="!repository" @click="snapshot">确认当前代码版本</el-button><el-button @click="tab='verify'">继续查看影响与复验</el-button></article></section>
   <section v-if="tab==='verify'" class="eng-section">
    <article class="eng-card"><h2>1. 确认要验证的代码版本</h2><p>在你自己的开发工具中打开下方仓库，修改并审阅代码，完成 Git 提交，再回来确认版本。系统不会把未提交修改或未跟踪文件算作执行内容。</p><p class="eng-path">{{repository||'当前未连接仓库：请从左侧创建版本库项目，或使用上面的领域案例。'}}</p><el-button :disabled="!repository" @click="snapshot">确认当前代码版本</el-button></article>
    <div class="eng-grid"><article class="eng-card"><h2>2. 审阅变化影响</h2><p>不确定的关系按保守范围处理；“未知”不能直接标为通过。</p><ul><li v-for="(u,i) in impact.unknown" :key="i"><NaturalData :value="u"/></li></ul><p>受影响内容 {{impact.affected?.length||0}} 项，计划执行 {{impact.tests.length}} 项测试。</p><details><summary>展开影响传播路径</summary><NaturalData :value="impact.paths"/></details><el-alert v-if="impact.test_mapping_gaps?.length" title="规则有新修订，部分测试映射尚未人工确认。请先审阅右侧测试。" type="warning" :closable="false"/><el-button @click="reviewImpact">我已审阅当前影响</el-button></article>
     <article class="eng-card"><h2>3. 核对测试覆盖</h2><p>测试文件路径相对于项目仓库。登记映射不表示测试已运行；每条测试必须人工核对确实覆盖所选规则。</p><div v-for="t in tests" :key="t.id" class="eng-record"><b>{{t.title}}</b><p>{{t.content.path}}，{{label(evidence.tests[t.id]?.verdict||'STALE')}}</p><el-button @click="reviewTest(t)">审阅并确认当前映射</el-button><el-button @click="editTest(t)">编辑登记</el-button><el-button @click="remove(t)">移除登记</el-button></div><details ref="testEditor" class="editor-focus"><summary>新增或编辑测试登记</summary><form class="eng-form" @submit.prevent="registerTest"><label>标题<input v-model="testForm.title" required/></label><label>测试文件<input v-model="testForm.path" required/></label><label>框架<select v-model="testForm.framework"><option value="unittest">Python 内置单元测试</option><option value="pytest">pytest（需环境已有）</option></select></label><label>关联代码文件，逗号分隔<input v-model="testForm.code_paths"/></label><fieldset><legend>验证的业务规则</legend><label v-for="r in rules" :key="r.id" class="eng-check"><input v-model="testForm.rule_ids" type="checkbox" :value="r.id"/>{{r.title}}</label></fieldset><p>编辑登记时会保留原有关联；只有在这里勾选或取消后才改变映射。</p><el-button type="primary" native-type="submit">确认测试登记</el-button><el-button @click="testForm={id:'',title:'公开验收测试',path:'',framework:'unittest',code_paths:'',rule_ids:[]}">改为新增登记</el-button></form></details><details><summary>登记代码文件</summary><input v-model="codePath" aria-label="代码相对路径"/><el-button @click="registerCode">登记代码</el-button></details></article></div>
    <article class="eng-card"><h2>4. 执行复验</h2><div class="eng-form"><label>执行方式<select v-model="executionMode"><option value="native">本机执行</option><option value="docker" :disabled="!capabilities.docker?.available">预配置容器隔离执行{{capabilities.docker?.available?'':'（暂不可用）'}}</option></select></label><p v-if="!capabilities.docker?.available">{{capabilities.docker?.reason}}</p><label v-if="executionMode==='native'" class="eng-check"><input v-model="trusted" type="checkbox"/>我已检查此项目可信，知晓本机执行不隔离宿主文件和权限</label><label class="eng-check"><input v-model="full" type="checkbox"/>运行所有已登记测试（取消勾选则按影响计划复验）</label><el-button type="primary" :disabled="running||!tests.length||(executionMode==='native'&&!trusted)" @click="verify">开始真实复验</el-button></div><p>测试进行中可以取消。完成后请查看每项结果；失败或未运行的测试需要处理后重试。</p></article>
    <article class="eng-card"><h2>5. 查看验证结果</h2><p>{{evidence.support_scope}}</p><div class="eng-record" v-for="c in evidence.conclusions" :key="c.rule_id"><b>{{c.title}}</b><el-tag :type="c.status==='PASS'?'success':'warning'">{{label(c.status)}}</el-tag></div><div v-for="r in evidence.runs" :key="r.id" class="eng-record"><b>{{formatDateTime(r.created_at)}} 的复验，{{label(r.status)}}</b><span>，{{versionName(r.baseline_id)}}</span><el-button v-if="['QUEUED','RUNNING','CANCELLING'].includes(r.status)" @click="act(async()=>{await api(`/runs/${r.id}/cancel`,'POST');await reload()})">取消运行</el-button><p v-if="r.result.reason">{{r.result.reason}}</p><div v-for="t in r.result.results||[]" :key="t.test_id"><p>{{tests.find((x:any)=>x.id===t.test_id)?.title||'未命名测试'}}：{{label(t.verdict)}}，耗时 {{t.seconds??0}} 秒</p><details><summary>查看测试技术输出（开发者）</summary><pre>{{t.output||t.reason}}</pre></details></div></div><p v-if="!evidence.runs.length">尚无真实运行记录。</p></article>
   </section>

   <section v-if="tab==='architecture'" class="eng-section"><div class="eng-grid"><article class="eng-card"><h2>设计约束与业务理由</h2><p>检查模块依赖和入口调用是否符合约定。无法确定的结果需要进一步核查。</p><div class="eng-record" v-for="a in architectures" :key="a.id"><b>{{a.title}}</b><p>作用文件：{{a.content.scope}}</p><p>业务理由：{{a.content.reason}}</p><p v-if="a.content.exception_until">例外：{{a.content.exception_reason}}，到期 {{a.content.exception_until}}</p><el-button @click="archForm={id:a.id,title:a.title,...a.content,forbidden_imports:a.content.forbidden_imports.join(','),required_calls:a.content.required_calls.join(','),entry_functions:a.content.entry_functions.join(',')}">修改约束</el-button><el-button @click="objectHistory(a)">历史理由</el-button><el-button @click="remove(a)">移除约束</el-button></div><el-button type="primary" :disabled="!architectures.length" @click="checkArchitecture">检查当前架构</el-button></article>
    <article class="eng-card"><h2>填写设计约束</h2><form class="eng-form" @submit.prevent="saveArchitecture"><label>约束标题<input v-model="archForm.title" required/></label><label>文件范围（支持 *）<input v-model="archForm.scope" required/></label><label>禁止导入模块（逗号分隔）<input v-model="archForm.forbidden_imports"/></label><label>入口必须先调用（逗号分隔）<input v-model="archForm.required_calls"/></label><label>指定入口函数（空表示公共函数）<input v-model="archForm.entry_functions"/></label><label>为什么需要这条约束<textarea v-model="archForm.reason" required rows="3"/></label><label>临时例外理由（可留空）<input v-model="archForm.exception_reason"/></label><label>例外到期日（填写例外时必填）<input v-model="archForm.exception_until" type="date"/></label><el-button type="primary" native-type="submit">保存架构候选</el-button><el-button @click="archForm.id=''">改为新增约束</el-button></form></article></div><article class="eng-card"><h2>当前架构结论：{{label(evidence.architecture.status)}}</h2><p>{{evidence.architecture.reason||evidence.architecture.scope}}</p><div v-for="(f,i) in evidence.architecture.findings||[]" :key="i" class="eng-record"><b>{{label(f.status)}}，{{f.path}}:{{f.line}}</b><p>{{f.reason}}</p><p>业务理由：{{f.business_reason||'请查看对应约束'}}</p><p>{{f.introduced===true?'相对上一代码版本新增':f.introduced===false?'上一版本已有':'缺少历史代码，新增情况未知'}}</p></div></article></section>

   <section v-if="tab==='negotiate'" class="eng-section"><article class="eng-card"><h2>比较需求调整方案</h2><p>先填写申请情况，再选择已与相关人员商定的调整范围。每次计算一组申请；预约的现有数量只统计与申请时段重叠的预约。</p><form class="eng-form eng-fields" @submit.prevent="solve"><label>总现有数量<input v-model.number="negotiation.existing" type="number" min="0"/></label><label>新增申请数量<input v-model.number="negotiation.incoming" type="number" min="0"/></label><label>新增申请所属分组<input v-model="negotiation.group"/></label><label>该组已有数量<input v-model.number="negotiation.group_existing" type="number" min="0"/></label><BusinessTimeInput v-model="negotiation.requested_start" label="申请开始"/><BusinessTimeInput v-model="negotiation.requested_end" label="申请结束"/><label>最多允许容量<input v-model.number="negotiation.capacity_limit" type="number" min="1"/></label><label>方案排序<select v-model="negotiation.preference"><option value="least_change">优先少改动</option><option value="admit_more">优先更多申请立即成功</option></select></label><label class="eng-check"><input v-model="negotiation.allow_waitlist" type="checkbox"/>允许部分新增申请候补</label><label class="eng-check"><input v-model="negotiation.allow_capacity_increase" type="checkbox"/>允许扩容</label><label class="eng-check"><input v-model="negotiation.allow_window_expansion" type="checkbox"/>允许扩大时间窗口</label><el-button type="primary" native-type="submit" :disabled="!ruleId">确认这些输入并计算方案</el-button></form></article><article v-for="d in negotiations" :key="d.id" class="eng-card"><h2>{{label(d.content.result.status)}}，{{label(d.status)}}</h2><p>{{versionName(d.baseline_id)}}，{{d.content.result.scope}}</p><ul><li v-for="(c,i) in d.content.result.conflicts" :key="i">{{readableNegotiation(c)}}</li></ul><p v-if="!d.content.result.candidates.length">保留当前硬约束时无解。先与相关人员讨论可调整项，再勾选获准的调整范围重新计算。</p><div v-for="(c,i) in d.content.result.candidates" :key="i" class="eng-record"><b>方案 {{Number(i)+1}}：容量 {{c.capacity}}，立即成功 {{c.admitted}}，候补 {{c.waiting}}</b><p>窗口 {{formatClock(c.window_start)}} 至 {{formatClock(c.window_end)}}</p><p>{{c.relaxed.map(readableNegotiation).join('；')||'不需放宽约束'}}</p><el-button :disabled="d.status!=='DRAFT'||d.baseline_id!==state.baseline_id" @click="adopt(d,Number(i))">人工采用这个方案</el-button></div></article></section>

   <section v-if="tab==='outcome'" class="eng-section"><article class="eng-card"><h2>记录实际使用效果</h2><p>记录观察对象、观察时间和实际结果，与修改前的情况比较，再说明下一步决定及理由。</p><form class="eng-form" @submit.prevent="saveOutcome"><label>观察标题<input v-model="outcomeForm.title" required/></label><label>现场观察或运行记录<textarea v-model="outcomeForm.observation" rows="4" required/></label><NumberEntries v-model="outcomeForm.metrics" label="运行指标（可选）"/><label>下一步决策<select v-model="outcomeForm.decision"><option value="OBSERVE">继续观察</option><option value="ADJUST">继续调整</option><option value="CLOSE" :disabled="!evidence.baseline_supported">确认结束本轮</option><option value="ROLLBACK">建议回退到上一版本（不会自动修改代码）</option></select></label><label>决策依据<textarea v-model="outcomeForm.rationale" required rows="3"/></label><el-button type="primary" native-type="submit" :disabled="!outcomeForm.metrics">确认运行观察与决策</el-button></form></article><article class="eng-card"><h2>已保存的运行评估</h2><p v-if="!outcomeRecords.length">还没有与复验证据关联的运行观察。</p><div v-for="o in outcomeRecords" :key="o.id" class="eng-record"><b>{{o.content.title}}</b><p>{{versionName(o.baseline_id)}}，{{o.baseline_id===state.baseline_id?'当前需求版本':'历史需求版本'}}，{{o.content.source}}</p><p>{{o.content.observation}}</p><p>决策：{{({OBSERVE:'继续观察',ADJUST:'继续调整',CLOSE:'结束本轮',ROLLBACK:'建议回退到上一版本'} as any)[o.content.decision]}}；{{o.content.rationale}}</p><details><summary>查看指标与验证结论</summary><NaturalData :value="{metrics:o.content.metrics,conclusions:o.content.conclusions}"/></details></div></article><el-button @click="tab='training'">继续查看过程复盘</el-button></section>
   <section v-if="tab==='training'" class="eng-section"><article v-if="artifacts?.length" class="eng-card"><h2>本项目的分析、验证与评估记录</h2><p>这些记录与下方的规则修订、复验和实践事件属于同一个项目。历史记录不自动代表当前结论。</p><details v-for="a in artifacts" :key="a.id"><summary>{{a.title}}，{{a.current_iteration===false?'历史参考':'当前轮次记录'}}</summary><NaturalData :value="a.data"/></details></article><article class="eng-card"><h2>需求变更实践与复盘</h2><p>先验证初始版本，再练习处理“容量增加 1”的新需求。确认变化后体验新规则、审阅影响、修改代码和测试，最后复验并记录使用效果。</p><p v-if="!evidence.baseline_supported">开始前请先完成当前版本的复验。</p><details><summary>参考分说明</summary><p>参考分用于回顾操作过程，不代表完整测试覆盖或学习成绩。</p></details><el-button type="primary" :disabled="!ruleId||!evidence.baseline_supported" @click="beginTraining">开始需求变更实践</el-button><div v-if="trainings.length" class="eng-select"><label>实践记录<select v-model="trainingId" @change="score=training?.content.submission||null"><option v-for="d in trainings" :key="d.id" :value="d.id">{{formatDateTime(d.created_at)}}（{{label(d.status)}}）</option></select></label></div><template v-if="training"><p>请围绕当前选定的业务规则完成本次变更，并保存每一步的证据。</p><p>本次目标：将容量调整为 {{training.content.target_capacity}}。</p><el-button :disabled="training.status!=='DRAFT'||!!training.content.change_baseline" @click="trainingChange">确认容量调整</el-button><el-button @click="act(async()=>{score=await api(`/training/${trainingId}/score`)})">查看当前参考分</el-button><el-button :disabled="training.status!=='DRAFT'" @click="submitTraining">提交实践记录</el-button></template><template v-if="score"><h3>实践过程参考分 {{score.score}} / {{score.maximum}}</h3><p>{{score.boundary}}</p><div class="eng-record" v-for="c in score.criteria" :key="c.title"><b>{{c.title}}，{{c.earned}} / {{c.weight}}</b><p>{{c.basis}}</p></div></template></article><article class="eng-card"><h2>版本与操作时间线</h2><p>时间均为北京时间。</p><details v-for="b in state.history.slice().reverse()" :key="b.id"><summary>{{b.title}}，{{formatDateTime(b.created_at)}}</summary><p>{{b.parent_id?'由上一需求版本演进而来':'项目的首个需求版本'}}；{{b.code_commit?'已关联代码版本':'尚未关联代码版本'}}；包含 {{Object.keys(b.members).length}} 项工程内容。</p></details><h3>操作记录</h3><div v-for="e in events.slice().reverse()" :key="e.id" class="eng-record"><b>{{label(e.kind)}}</b><span>，{{formatDateTime(e.created_at)}}</span><details><summary>查看操作说明</summary><NaturalData :value="e.details"/></details></div></article></section>
  </template>
  <el-dialog v-model="architectureReviewOpen" title="审阅工程设计候选" width="min(900px,94vw)"><p>核对文件范围、入口约束、业务理由和临时例外。确认后才会形成新的正式需求版本。</p><div v-for="d in architectureCandidates" :key="d.id" class="eng-record"><h3>{{d.content.title}}</h3><NaturalData :value="d.content.changes"/><el-button type="primary" :disabled="d.baseline_id!==state.baseline_id" @click="accept(d)">确认新需求版本</el-button><el-button @click="act(async()=>{await api(`/drafts/${d.id}/cancel`,'POST');await reload()})">放弃候选</el-button></div><p v-if="!architectureCandidates.length">当前没有待确认的工程设计候选。</p></el-dialog>
  <el-dialog v-model="historyOpen" title="规则修订历史" width="min(850px,90vw)"><div v-for="r in history" :key="r.id" class="eng-record"><h3>第 {{r.number}} 次修订：{{r.title}}</h3><p>{{formatDateTime(r.created_at)}}</p><NaturalData :value="r.content"/></div></el-dialog>
 </section>
</template>
